import{z as s,x as o,o as E,c as m,q as A,j as r,D as e,d as B,s as t,S as n,b as l}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"MBR 解码","description":"","frontmatter":{"title":"MBR 解码","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/mbr-decoding.md","filePath":"llm/mbr-decoding.md","lastUpdated":1791413859000}'),p={name:"llm/mbr-decoding.md"};function d(M,a,D,h,c,R){const i=o("Mermaid");return E(),m("div",null,[a[2]||(a[2]=A('<h1 id="mbr-解码" tabindex="-1">MBR 解码 <a class="header-anchor" href="#mbr-解码" aria-label="Permalink to &quot;MBR 解码&quot;">​</a></h1><div class="epigraph"><p>不要交付众数，交付在期望效用下最好的那一条：用样本近似后验，再用任务度量当损失函数。</p><footer>—— Eikema &amp; Aziz, Is MAP Decoding All You Need?, COLING 2020；神经度量上的 MBR 见 Freitag et al., 2022</footer></div><p><a href="/llm/diverse-beam-search">上一课</a>把束掰成多条脊，交付的仍是「某条脊上的 MAP」。本课改交付规则：最小贝叶斯风险（MBR）不找 \\(\\arg\\max_y \\pi(y\\mid x)\\)，而找使期望损失最小的 \\(y\\)。机器翻译里 Kumar 与 Byrne 早已用 MBR；Eikema 与 Aziz 指出神经 MT 的众数往往是退化的，应从模型的 <em>样本</em> 里估后验，再用 BLEU 或神经度量选代表。后课的层对比与上下文对比，是逐步改分布；MBR 是序列级重排，先修这一层。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/llm/length-penalty-degeneration">长度惩罚</a>与 DBS 都还在 MAP 家族里打转：一条假设的好坏等于它自己的 \\(\\log\\pi\\) 加减惩罚。人在意的是效用：翻译是否充分、摘要是否漏点、答案是否可核对。MAP 的众数可以是「安全套话」，期望效用的最优可以是一条概率不最高、但与许多样本都接近的句子。缺口是：已经有一堆候选（束、DBS、或温度采样）之后，如何用它们互相当证据，而不是再看一遍 \\(\\pi\\)。</p><p>MBR 的代价立刻出现：要对候选两两算效用，成本 \\(O(N^2)\\) 次度量前向。神经度量（COMET、BLEURT）本身是模型，N=64 的 MBR 可能比再生成一次更贵。本课把「选哪条」从「生成哪条」拆开，不把度量训练写进来。</p><p><span class="marginnote">算一笔账：\\(N=64\\) 时两两配对有 \\(64\\times 63/2=2016\\) 次，每次都要跑一遍度量模型的前向；若度量是 COMET 这样的神经模型，这套「选代表」的开销常常超过重新生成一次译文。所以 MBR 多用于离线翻译与评测，不塞进实时对话。</span></p><p><span class="marginnote">MBR 不是多数票。多数票在 <em>答案空间</em> 上计数，见 <a href="/llm/self-consistency">Self-Consistency</a>。MBR 在 <em>字符串或嵌入空间</em> 上最小化期望损失，即使没有可解析的最终答案也能用——这也是它比投票更贵的原因。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从 \\(\\pi(\\cdot\\mid x)\\) 抽（或束出）集合 \\(\\mathcal{Y}=\\{y_1,\\ldots,y_N\\}\\)。选</p> \\[\\hat y=\\arg\\min_{y\\in\\mathcal{Y}}\\sum_{y&#39;\\in\\mathcal{Y}}\\ell(y,y&#39;), \\]<p>其中 \\(\\ell\\) 是任务损失（\\(1-\\)BLEU、一减 COMET、编辑距离）。这是用样本对后验做蒙特卡洛、并用 \\(\\mathcal{Y}\\) 同时当假设集与证据集的常用近似。\\(\\ell\\) 必须与任务同向：开放聊天没有稳定 \\(\\ell\\)，MBR 会把文风推向度量模型的偏好，与 RM 上的 Best-of-N 同一类风险。</p><p><span class="marginnote">「期望损失最小」翻译成大白话：把每条候选跟其他所有候选各比一次，谁「平均起来离大家最近」谁当选。可以想象在一群人里选代表——不选嗓门最大的（众数），而选和谁都聊得来的「最合群」的那位（中位中心）。</span></p><p>候选从哪来决定覆盖。只用普通束，MBR 重排的是同一脊上的微扰，收益小；用 <a href="/llm/sampling-temperature-topp">温度</a> 采样或 DBS，证据集才张开。Freitag 等人表明：用神经度量当 \\(\\ell\\)，MT 上 MBR 可超过把度量当 reranker 只打 \\(\\pi\\) 的基线——因为比较的是假设之间，不是假设与源的绝对分。</p>',14)),(E(),r(n,null,{default:e(()=>[t(i,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E6%8F%90%E7%A4%BA%20x%22%5D%20--%3E%20S%5B%22%E9%87%87%E6%A0%B7%E6%88%96%20DBS%20%E5%BE%97%E5%88%B0%20N%20%E6%9D%A1%22%5D%0A%20%20S%20--%3E%20L%5B%22%E4%B8%A4%E4%B8%A4%E6%95%88%E7%94%A8%20%E2%84%93%22%5D%0A%20%20L%20--%3E%20Y%5B%22%E6%9C%9F%E6%9C%9B%E6%8D%9F%E5%A4%B1%E6%9C%80%E5%B0%8F%E7%9A%84%E4%B8%80%E6%9D%A1%22%5D%0A%20%20PI%5B%22%E5%8F%AA%E7%9C%8B%20log%20%CF%80%22%5D%20--%3E%20MAP%5B%22%E4%BC%97%E6%95%B0%20%2F%20%E5%A5%97%E8%AF%9D%E9%A3%8E%E9%99%A9%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=l("h2",{id:"机制",tabindex:"-1"},[B("机制 "),l("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=l("p",null,"若 \\(\\pi\\) 把质量铺在一个语义簇上，MBR 的最优接近该簇的「中心」，对个别噪声样本稳健。若 \\(\\pi\\) 是多峰且各峰效用不同，\\(\\ell\\) 负责挑峰：BLEU 会偏向 n-gram 中心，神经度量会偏向其训练过的「好翻译」流形。假阳性与 RM 过优化同构：\\(N\\to\\infty\\) 时交付的是 \\(\\ell\\) 的模式。因此 MBR 的上限是度量，不是生成器覆盖——覆盖只保证中心能被样本碰到。",-1)),(E(),r(n,null,{default:e(()=>[t(i,{id:"mermaid-45",class:"mermaid",graph:"flowchart%20TD%0A%20%20subgraph%20U%5B%22%E5%8D%95%E5%B3%B0%EF%BC%9A%E8%B4%A8%E9%87%8F%E9%93%BA%E5%9C%A8%E4%B8%80%E4%B8%AA%E8%AF%AD%E4%B9%89%E7%B0%87%22%5D%0A%20%20%20%20A%5B%22%E6%A0%B7%E6%9C%AC%E8%81%9A%E5%9C%A8%E4%B8%80%E5%A4%84%22%5D%20--%3E%20B%5B%22MBR%20%E4%BA%A4%E4%BB%98%E7%B0%87%E4%B8%AD%E5%BF%83%22%5D%0A%20%20%20%20B%20--%3E%20C%5B%22%E4%B8%AA%E5%88%AB%E5%99%AA%E5%A3%B0%E6%A0%B7%E6%9C%AC%E6%92%BC%E4%B8%8D%E5%8A%A8%E7%BB%93%E6%9E%9C%22%5D%0A%20%20end%0A%20%20subgraph%20M%5B%22%E5%A4%9A%E5%B3%B0%EF%BC%9A%E5%87%A0%E4%B8%AA%E4%B8%8D%E5%90%8C%E8%AF%91%E6%96%87%E6%B5%81%E5%BD%A2%22%5D%0A%20%20%20%20D%5B%22BLEU%20%E5%81%8F%E5%90%91%20n-gram%20%E4%B8%AD%E5%BF%83%E5%B3%B0%22%5D%0A%20%20%20%20E%5B%22%E7%A5%9E%E7%BB%8F%E5%BA%A6%E9%87%8F%E5%81%8F%E5%90%91%E5%85%B6%E8%AE%AD%E7%BB%83%E6%B5%81%E5%BD%A2%22%5D%0A%20%20end%0A%20%20D%20--%3E%20F%5B%22N%20%E8%B6%8B%E5%90%91%E6%97%A0%E7%A9%B7%E6%97%B6%E4%BA%A4%E4%BB%98%20%E2%84%93%20%E7%9A%84%E6%A8%A1%E5%BC%8F%22%5D%0A%20%20E%20--%3E%20F%0A%20%20F%20--%3E%20G%5B%22%E4%B8%8A%E9%99%90%E7%94%B1%E5%BA%A6%E9%87%8F%E7%9A%84%E6%A0%A1%E5%87%86%E5%86%B3%E5%AE%9A%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">常见误区：初学者容易以为「概率最高的句子质量一定最好」。实际上概率高只说明这句话在训练分布里常见——「这是译文。」之类的安全套话概率往往最高，但未必是可用译文；MBR 正是为了绕开这个众数陷阱才去算期望效用。</span></p><p><span class="marginnote">对称 \\(\\ell(y,y&#39;)=\\ell(y&#39;,y)\\) 时，MBR 选出的是集合的中位；不对称损失（漏翻 vs 过翻）会改变中心。不要默认所有度量可交换。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>延迟敏感的对话不要默认 MBR：\\(O(N^2)\\) 次 COMET 前向会把 TPOT 打穿。离线 MT、评测、数据过滤更合适。数学题应先解析再在答案空间投票，不要对整段思维链做 BLEU-MBR。候选必须独立或至少多样；对贪心的 \\(N\\) 份复制做 MBR 退化（所有候选相同，选谁都一样）。</p><p>出处：Eikema &amp; Aziz, COLING 2020；Freitag et al., 2022（神经度量 MBR）。经典 MT 的 MBR 见 Kumar &amp; Byrne。不要发明「LLM-MBR」的 arXiv 编号。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MBR 最小化期望任务损失，不最大化 \\(\\pi\\)；交付的是样本集的中心而非众数。</li><li>候选要用采样或 DBS 张开；普通束上的 MBR 收益薄。</li><li>成本是 \\(O(N^2)\\) 次度量；上限由 \\(\\ell\\) 的校准决定。</li><li>可解析答案上，投票通常更便宜、更对症。</li><li>开放生成的 \\(\\ell\\) 会把文风推向度量模型。</li><li>后课改逐步分布，不再假设已经有一套序列级度量。</li><li>出处：Eikema &amp; Aziz, COLING 2020；Freitag et al., 2022。</li></ul>',7))])}const _=s(p,[["render",d]]);export{g as __pageData,_ as default};
